 static int NaxxHand(MatchEngine g,string card,int seat=0){int next=id++;g.Players[seat].Hand.Add(new HandCard{Id=next,CardId=card});return next;}
 static void NaxxKill(MatchEngine g,BattleUnit unit){unit.DamageTaken=unit.MaxHealth;g.Cleanup();}
 static void NaxxCards(){
